SELECT CAST(p.id AS CHAR) AS id, p.title, p.description, p.creator_id AS creatorId, u.nickname AS creatorNickname, p.status, p.visible, p.is_top AS isTop, p.type, p.tags, p.create_time AS createTime, p.publish_time AS publishTime FROM know_posts p LEFT JOIN users u ON p.creator_id = u.id
AND p.title LIKE CONCAT('%', #{keyword}, '%')
AND p.status = #{status}
AND p.visible = #{visible}
AND p.creator_id = #{creatorId}
ORDER BY p.create_time DESC, p.id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM know_posts p


        AND p.title LIKE CONCAT('%', #{keyword}, '%')


        AND p.status = #{status}


        AND p.visible = #{visible}


        AND p.creator_id = #{creatorId}

mapper.update:
UPDATE know_posts
SET visible = #{visible}, update_time = NOW()
WHERE id = #{id}

UPDATE know_posts
SET is_top = #{isTop}, update_time = NOW()
WHERE id = #{id}

UPDATE know_posts
SET status = 'deleted', update_time = NOW()
WHERE id = #{id}
